tokens.css:
:root{
  /* durations — ladder grows with travel distance / surface area (M3 + Carbon) */
  --dur-xs: 100ms;   /* micro: button/toggle/tooltip/hover/focus ring */
  --dur-sm: 150ms;   /* small state change, chip, checkbox */
  --dur-md: 250ms;   /* DEFAULT enter / section reveal / crossfade-out */
  --dur-lg: 400ms;   /* larger surface: chart morph, accordion height, crossfade-in */
  --dur-xl: 600ms;   /* full-bleed / scrolly act transition */
  --dur-count: 900ms;/* number count-up / odometer */

  /* easings — M3 emphasized/standard set */
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);     /* begins AND ends on screen — the default */
  --ease-out:      cubic-bezier(0.05, 0.7, 0.1, 1);/* entering: starts off-screen, settles on */
  --ease-in:       cubic-bezier(0.3, 0, 0.8, 0.15);/* exiting: leaves the screen */
  --ease-in-out:   cubic-bezier(0.4, 0, 0.2, 1);   /* moves within the screen */
  --ease-spring:   cubic-bezier(0.34, 1.56, 0.64, 1);/* gentle overshoot — PLAYFUL ONLY, never a utility */

  /* choreography */
  --stagger: 60ms;   /* per-item reveal delay; cap total < ~500ms (so ~6 items max) */
}

@media (prefers-reduced-motion: reduce){
  :root{
    --dur-xs: 1ms; --dur-sm: 1ms; --dur-md: 1ms; --dur-lg: 1ms;
    --dur-xl: 1ms; --dur-count: 1ms; --stagger: 0ms;
  }
  /* belt-and-braces: also kill any author keyframe animations that don't read tokens */
  *, *::before, *::after{ animation-duration: 1ms !important; animation-iteration-count: 1 !important; transition-duration: 1ms !important; scroll-behavior: auto !important; }
}

reveal_visible_by_default.css:
/* No JS / JS not yet running -> NOTHING is hidden (no html.js-reveal class, so this rule never matches). */
/* Gate fires only once JS adds .js-reveal to <html>, and never on a figure / [data-vis] / .chart (async visuals must not wait on the observer). */
html.js-reveal .reveal:not(.in) > *:not(figure):not([data-vis]):not(.chart){ opacity:0; transform:translateY(8px); transition: opacity var(--dur-md) var(--ease-out), transform var(--dur-md) var(--ease-out); transition-delay: calc(var(--i, 0) * var(--stagger)); }
html.js-reveal .reveal.in > *{ opacity:1; transform:none; }

reveal_visible_by_default.js:
// Confirm JS is running BEFORE arming the gate, so the opacity:0 above only ever applies when something can remove it.
document.documentElement.classList.add('js-reveal');
const REVEAL_REDUCE = matchMedia('(prefers-reduced-motion: reduce)').matches;
const revealIO = new IntersectionObserver((entries, obs) => {
  for (const e of entries) if (e.isIntersecting){ e.target.classList.add('in'); obs.unobserve(e.target); }
}, { rootMargin: '0px 0px -10% 0px' });
for (const el of document.querySelectorAll('.reveal')){
  // Above-the-fold sections must not wait on the observer: reveal them immediately.
  const r = el.getBoundingClientRect();
  if (REVEAL_REDUCE || r.top < window.innerHeight){ el.classList.add('in'); }
  else revealIO.observe(el);
}

count_up.js:
const REDUCE = matchMedia('(prefers-reduced-motion: reduce)').matches;
const DUR = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--dur-count')) || 900;
const easeOutCubic = t => 1 - Math.pow(1 - t, 3);
function runCount(el){
  const to = parseFloat(el.dataset.to);
  const dec = parseInt(el.dataset.decimals || '0', 10);
  if (REDUCE){ el.textContent = to.toFixed(dec); return; }
  const start = performance.now();
  (function tick(now){
    const p = Math.min((now - start) / DUR, 1);
    el.textContent = (to * easeOutCubic(p)).toFixed(dec);
    if (p < 1) requestAnimationFrame(tick);
    else el.textContent = to.toFixed(dec); // exact final value
  })(start);
}
const io = new IntersectionObserver((entries, obs) => {
  for (const e of entries) if (e.isIntersecting){ runCount(e.target); obs.unobserve(e.target); }
}, { threshold: 0.6 });
document.querySelectorAll('.stat-num').forEach(el => io.observe(el));

hover_focus.css:
.link{ transition: color var(--dur-xs) var(--ease-standard), text-decoration-color var(--dur-xs) var(--ease-standard); }
.link:hover, .link:focus-visible{ text-decoration-line: underline; }
.card{ transition: transform var(--dur-sm) var(--ease-standard); }
.card:hover, .card:focus-visible{ transform: translateY(-2px); }

skeleton_to_content.css:
.skeleton{ position:relative; background:var(--surface,#eee); border-radius:6px; }
.skeleton::after{ content:''; position:absolute; inset:0; transform:translateX(-100%); background:linear-gradient(90deg, transparent, rgba(255,255,255,.4), transparent); animation: shimmer 1.2s infinite; }
@media (prefers-reduced-motion: reduce){ .skeleton::after{ animation: none; } }
@keyframes shimmer{ to{ transform:translateX(100%); } }
.embed{ opacity:0; transition: opacity var(--dur-md) var(--ease-out); }
.embed.ready{ opacity:1; }
